import numpy as np
def vmat_gauss(ex, cs, gs):
    n = (2 * ex / np.pi) ** 0.75
    p = ex[:, None] + ex[None, :]
    return sum(c * np.outer(n, n) * (np.pi / (p + g)) ** 1.5 for c, g in zip(cs, gs))
def vmat_erf(ex, q, mu):
    n = (2 * ex / np.pi) ** 0.75
    p = ex[:, None] + ex[None, :]
    return -q * np.outer(n, n) * 2 * np.pi / p * np.sqrt(mu / (p + mu))
ex = 0.03 * 2.1 ** np.arange(12)
V = vmat_erf(ex, 4.0, 2.5)
assert np.allclose(importance_selected_products(V.copy(), ex.copy(), 0.0001), target)

